/**
 * CHARACTERIZATION of the schema-management options as they were BEFORE `DB_SCHEMA_MODE` existed.
 *
 * `schemaMode.legacy.fixture.json` was generated by running the original `databases.ts` over the cross-product of
 * engine × NODE_ENV × DB_SYNC × TYPEORM_SYNC × DB_MIGRATIONS_RUN × DB_SQLITE_MIGRATIONS (plus a few spellings: `1`, `0`,
 * `TRUE`, ` true `, `yes`, empty). Each value is three digits: `synchronize`, `migrationsRun`, `migrations loaded`.
 * Seven apps depend on these combinations (DB_SCHEMA_MODE unset): this table must stay green forever; it is the
 * "nothing changes without DB_SCHEMA_MODE" contract. Never regenerate it from a new implementation.
 */

import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { mkdtempSync, readFileSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { buildMainDataSourceOptions } from './databases';

const KEYS = [
  'DB_ENGINE', 'DATABASE_ENGINE', 'DB_PATH', 'DB_SYNC', 'TYPEORM_SYNC', 'DB_MIGRATIONS_RUN', 'DB_SQLITE_MIGRATIONS',
  'DB_SCHEMA_MODE', 'NODE_ENV', 'DB_CONNECTIONS', 'DB_MODULE_ROUTING', 'TYPEORM_CLI',
];

const fixture = JSON.parse(readFileSync(join(__dirname, 'schemaMode.legacy.fixture.json'), 'utf8')) as Record<string, string>;

describe('legacy schema options (DB_SCHEMA_MODE unset) are unchanged', () => {
  let saved: Record<string, string | undefined>;
  let dir: string;

  beforeEach(() => {
    saved = {};
    for (const k of KEYS) {
      saved[k] = process.env[k];
      delete process.env[k];
    }
    dir = mkdtempSync(join(tmpdir(), 'vx-schema-'));
    jest.spyOn(console, 'warn').mockImplementation(() => undefined);
    jest.spyOn(console, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => {
    for (const k of KEYS) {
      if (saved[k] === undefined) delete process.env[k];
      else process.env[k] = saved[k];
    }
    jest.restoreAllMocks();
  });

  it('pins every recorded combination', () => {
    const ctx = { baseDir: join(dir, 'src'), migrationGlobs: [join(dir, 'src/migrations/*.{js,ts}')], certBaseDir: dir };
    const failures: string[] = [];
    for (const [key, expected] of Object.entries(fixture)) {
      const [engine, nodeEnv, dbSync, typeormSync, migrationsRun, sqliteMigrations] = JSON.parse(key) as [string, string | null, string | null, string | null, string | null, string | null];
      for (const k of KEYS) delete process.env[k];
      process.env.DATABASE_ENGINE = engine;
      if (engine === 'sqlite') process.env.DB_PATH = ':memory:';
      const set = (name: string, value: string | null) => {
        if (value !== null) process.env[name] = value;
      };
      set('NODE_ENV', nodeEnv);
      set('DB_SYNC', dbSync);
      set('TYPEORM_SYNC', typeormSync);
      set('DB_MIGRATIONS_RUN', migrationsRun);
      set('DB_SQLITE_MIGRATIONS', sqliteMigrations);
      const options = buildMainDataSourceOptions(ctx) as { synchronize?: boolean; migrationsRun?: boolean; migrations?: string[] };
      const actual = `${options.synchronize ? 1 : 0}${options.migrationsRun ? 1 : 0}${(options.migrations ?? []).length > 0 ? 1 : 0}`;
      if (actual !== expected) failures.push(`${key} expected ${expected} got ${actual}`);
    }
    expect(Object.keys(fixture).length).toBeGreaterThan(600);
    expect(failures).toEqual([]);
  });
});
